import { sendEmail } from "./email.service.js";

const retryAt = (attempts) => new Date(Date.now() + Math.min(60, 2 ** attempts) * 60 * 1000);

export const queueEmail = async ({ idempotencyKey, toEmail, type, data }) => {
  return prisma.emailOutbox.upsert({
    where: { idempotencyKey },
    update: {},
    create: {
      idempotencyKey,
      toEmail,
      type,
      payload: JSON.stringify(data),
    },
  });
};

export const deliverQueuedEmail = async (idempotencyKey) => {
  const entry = await prisma.emailOutbox.findUnique({ where: { idempotencyKey } });
  if (!entry || entry.status === "SENT" || entry.status === "SKIPPED") return entry;

  const result = await sendEmail({
    to: entry.toEmail,
    type: entry.type,
    data: JSON.parse(entry.payload),
  });
  const attempts = entry.attempts + 1;
  const status = result.status === "sent" ? "SENT" : result.status === "skipped" ? "SKIPPED" : "FAILED";

  return prisma.emailOutbox.update({
    where: { idempotencyKey },
    data: {
      status,
      attempts,
      sentAt: status === "SENT" || status === "SKIPPED" ? new Date() : null,
      lastError: status === "FAILED" ? String(result.error || "Email delivery failed").slice(0, 500) : null,
      nextAttemptAt: status === "FAILED" ? retryAt(attempts) : new Date(),
    },
  });
};

import { prisma } from "../config/prisma.js";
import { AppError } from "../utils/AppError.js";
import { deliverQueuedEmail, queueEmail } from "./email-outbox.service.js";

export const REVIEW_STATUSES = new Set([
  "NEW",
  "REVIEWING",
  "SHORTLISTED",
  "INTERVIEW_SCHEDULED",
  "INTERVIEWED",
  "HIRED",
  "REJECTED",
]);

const shortlistPayload = ({ application, job }) => ({
  applicantName: application.name,
  jobTitle: job.designation,
  companyName: job.companyName,
  nextStep: "The recruiter will contact you with interview details.",
});

export const getRecruiterApplication = async (applicationId, recruiterId) => {
  const application = await prisma.application.findFirst({
    where: { id: applicationId, job: { recruiterId } },
    include: {
      job: true,
      statusHistory: { orderBy: { createdAt: "desc" } },
    },
  });

  if (!application) throw new AppError("Application not found.", 404);
  return application;
};

export const updateRecruiterApplication = async ({ applicationId, recruiterId, status, recruiterNote }) => {
  if (!REVIEW_STATUSES.has(status)) throw new AppError("Select a valid application status.", 400);
  if (recruiterNote.length > 2000) throw new AppError("Recruiter notes must be 2,000 characters or fewer.", 400);

  const current = await getRecruiterApplication(applicationId, recruiterId);
  const changedStatus = current.status !== status;
  const shortlistKey = `APPLICATION_SHORTLISTED:${applicationId}`;

  await prisma.$transaction(async (tx) => {
    await tx.application.update({
      where: { id: applicationId },
      data: {
        status,
        recruiterNote: recruiterNote || null,
        statusUpdatedAt: changedStatus ? new Date() : current.statusUpdatedAt,
      },
    });

    if (changedStatus) {
      await tx.applicationStatusHistory.create({
        data: {
          applicationId,
          actorId: recruiterId,
          fromStatus: current.status,
          toStatus: status,
        },
      });
    }

    if (changedStatus && status === "SHORTLISTED") {
      await tx.emailOutbox.upsert({
        where: { idempotencyKey: shortlistKey },
        update: {},
        create: {
          idempotencyKey: shortlistKey,
          toEmail: current.email,
          type: "APPLICATION_SHORTLISTED",
          payload: JSON.stringify(shortlistPayload({ application: current, job: current.job })),
        },
      });
    }
  });

  if (changedStatus && status === "SHORTLISTED") await deliverQueuedEmail(shortlistKey);
  return getRecruiterApplication(applicationId, recruiterId);
};

import nodemailer from "nodemailer";
import { env } from "../config/env.js";
import { prisma } from "../config/prisma.js";

let transporter = null;

const escapeHtml = (value) =>
  String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");

const getTransporter = () => {
  if (!env.email.enabled) return null;
  if (!transporter) {
    transporter = nodemailer.createTransport({
      service: env.email.service || "gmail",
      auth: {
        user: env.email.user,
        pass: env.email.pass,
      },
    });
  }
  return transporter;
};

const templates = {
  EMAIL_VERIFY: ({ name, verifyUrl }) => ({
    subject: "Verify your Easily Jobs email",
    text: `Hi ${name},\n\nPlease verify your email by opening this link:\n${verifyUrl}\n\nThis link expires in 24 hours.\n\n— Easily Jobs`,
    html: `<p>Hi <strong>${escapeHtml(name)}</strong>,</p>
      <p>Please verify your email to activate your Easily Jobs account.</p>
      <p><a href="${escapeHtml(verifyUrl)}" style="display:inline-block;padding:10px 18px;background:#0d9488;color:#fff;text-decoration:none;border-radius:8px;">Verify email</a></p>
      <p style="color:#64748b;font-size:13px;">Or paste this URL: ${escapeHtml(verifyUrl)}</p>
      <p style="color:#64748b;font-size:13px;">This link expires in 24 hours.</p>`,
  }),
  APPLICATION_RECEIVED: ({ name, jobTitle, companyName }) => ({
    subject: `Application received — ${jobTitle}`,
    text: `Hi ${name},\n\nWe received your application for "${jobTitle}" at ${companyName}. The recruiter will review it soon.\n\n— Easily Jobs`,
    html: `<p>Hi <strong>${escapeHtml(name)}</strong>,</p>
      <p>We received your application for <strong>${escapeHtml(jobTitle)}</strong> at <strong>${escapeHtml(companyName)}</strong>.</p>
      <p>The recruiter will review it soon. Good luck!</p>
      <p style="color:#64748b;">— Easily Jobs</p>`,
  }),
  APPLICATION_NOTIFY_RECRUITER: ({ recruiterName, applicantName, jobTitle }) => ({
    subject: `New applicant for ${jobTitle}`,
    text: `Hi ${recruiterName},\n\n${applicantName} applied to "${jobTitle}".\n\nLog in to your dashboard to review the application.\n\n— Easily Jobs`,
    html: `<p>Hi <strong>${escapeHtml(recruiterName)}</strong>,</p>
      <p><strong>${escapeHtml(applicantName)}</strong> just applied to <strong>${escapeHtml(jobTitle)}</strong>.</p>
      <p><a href="${env.appUrl}/recruiter">Open your dashboard</a></p>`,
  }),
  APPLICATION_SHORTLISTED: ({ applicantName, jobTitle, companyName, nextStep }) => ({
    subject: `You have been shortlisted — ${jobTitle}`,
    text: `Hi ${applicantName},\n\nYou have been shortlisted for "${jobTitle}" at ${companyName}.\n\n${nextStep}\n\n— Easily Jobs`,
    html: `<p>Hi <strong>${escapeHtml(applicantName)}</strong>,</p>
      <p>You have been shortlisted for <strong>${escapeHtml(jobTitle)}</strong> at <strong>${escapeHtml(companyName)}</strong>.</p>
      <p>${escapeHtml(nextStep)}</p>
      <p style="color:#64748b;">— Easily Jobs</p>`,
  }),
};

/**
 * Sends an email and writes an EmailLog row.
 * Never throws to the caller for transport failures (logged as failed).
 */
export const sendEmail = async ({ to, type, data }) => {
  const tpl = templates[type];
  if (!tpl) {
    throw new Error(`Unknown email type: ${type}`);
  }
  const { subject, text, html } = tpl(data);
  const active = getTransporter();

  if (!active) {
    console.log(`[email skipped] ${type} → ${to} | ${subject}`);
    await prisma.emailLog.create({
      data: { toEmail: to, subject, type, status: "skipped" },
    });
    return { status: "skipped" };
  }

  try {
    await active.sendMail({
      from: env.email.from,
      to,
      subject,
      text,
      html,
    });
    await prisma.emailLog.create({
      data: { toEmail: to, subject, type, status: "sent" },
    });
    return { status: "sent" };
  } catch (error) {
    console.error("Email send failed:", error.message);
    await prisma.emailLog.create({
      data: {
        toEmail: to,
        subject,
        type,
        status: "failed",
        error: String(error.message).slice(0, 500),
      },
    });
    return { status: "failed", error: error.message };
  }
};

export const sendVerificationEmail = async (user, verifyToken, appUrl = env.appUrl) => {
  const verifyUrl = `${appUrl.replace(/\/$/, "")}/verify-email?token=${encodeURIComponent(verifyToken)}`;
  const result = await sendEmail({
    to: user.email,
    type: "EMAIL_VERIFY",
    data: { name: user.name, verifyUrl },
  });

  if (result.status !== "sent" && !env.isProd) {
    console.warn(`[email ${result.status}] Verification URL: ${verifyUrl}`);
  }
  return result;
};

export const sendApplicationEmails = async ({ applicant, job, recruiter }) => {
  await sendEmail({
    to: applicant.email,
    type: "APPLICATION_RECEIVED",
    data: {
      name: applicant.name,
      jobTitle: job.designation,
      companyName: job.companyName,
    },
  });

  if (recruiter?.email) {
    await sendEmail({
      to: recruiter.email,
      type: "APPLICATION_NOTIFY_RECRUITER",
      data: {
        recruiterName: recruiter.name,
        applicantName: applicant.name,
        jobTitle: job.designation,
      },
    });
  }
};

